 "content": "from collections import Counter

def transform(grid):
    """Mark the background gap between repeated non-background cells."""
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 2)
    background = counts.most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == row[c + 1] != background:
                out[r][c] = 2
    return out
